FUNCTION_BLOCK JamPumpControl
VAR_INPUT
    VISCOSITY_OK : BOOL;
    PASTE_E_STOP_NC : BOOL;
    DebounceTime : TIME;
    CycleTime : TIME;
END_VAR
VAR_OUTPUT
    VFD_RUN : BOOL := FALSE;
    PUMP_MAINT_DUE : BOOL := FALSE;
    PUMP_RUNTIME_ACC : LTIME := LTIME#0s;
END_VAR
VAR
    ViscosityValid : BOOL := FALSE;
    DebounceTimer : LTIME := LTIME#0s;
    CycleTime_LTIME : LTIME;
    DebounceTime_LTIME : LTIME;
END_VAR
```

