    // Only accumulate debounce time when emergency stop is not active
    IF PASTE_E_STOP_NC THEN
        DebounceTimer := DebounceTimer + CycleTime_LTIME;
    ELSE
        // Emergency stop clears incomplete debounce timing
        DebounceTimer := LTIME#0s;
    END_IF;
    IF DebounceTimer >= DebounceTime_LTIME THEN
        ViscosityValid := TRUE;
        DebounceTimer := DebounceTime_LTIME; // optional clamp
    END_IF;
END_IF;

// Emergency stop priority: immediate disable if e-stop false
